// (style factory, seed 1): boot → conveyors → assembly → logistics → storage → launch pad → night shift.
// Themes: A — Conveyor Dawn (город) (recomposed), B — лид из synthwave (as written); the bridge melody is newly
// composed on the rhythm of a theme from lofi. Computed parts: an improvised solo, a counter-melody from the chords, the theme at half speed in the outro, a key change up.
// It is an ordinary song file: change anything; the melodies can be drawn in the piano roll (P).
// x is time in beats; n counts semitones from C4 (MIDI 60).
import { TAU, delay, exp, filter, floor, hz, mod, noise, osc, reverb, sin, smooth, supersaw } from '../src/engine.js'
import {
  arrangement, chorus, clankTone, clapDrum, clubKick, crashCymbal, duck, fm, hash, hatDrum, improvise, kickDrum, monoSynth, notesAt, pan, pluckTone, poly, rimDrum, shakerDrum, snareDrum, strings, trigger,
} from '../src/instruments.js'

const SECTIONS = [[0,"boot"],[16,"conveyors"],[80,"assembly"],[112,"logistics"],[176,"storage"],[208,"launch pad"],[272,"night shift"]]
const END = 288
const part = arrangement(SECTIONS)
const is = (x, ...names) => names.includes(part(x).name)
const C4 = 440 * 2 ** (-9 / 12) // 261.63 Hz, exact equal temperament
const SW = 0.5 // the off-beat eighth lands at 0.5 of the beat
const ROLE = [[0,"intro",1],[16,"theme",2],[80,"themeB",2],[112,"solo",3],[176,"bridge",1],[208,"final",3],[272,"outro",1]] // [start, role, energy 0–3] per section
const sectionOf = x => { let s = ROLE[0]; for (const r of ROLE) if (r[0] <= x) s = r; return s }
const energy = x => (x < END ? sectionOf(x)[2] : -1)
const role = x => (x < END ? sectionOf(x)[1] : 'end')

